import { act, fireEvent, render, screen } from '@testing-library/react';
import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest';
import { usePollingRequest } from './Solution';

/**
 * 断言由 fe_gen.py 里的 _Sim 时间线模型生成，不手算 ——
 * react-vitest 题的判分事实来源就是这份文件，抄错一次就永久错一次。
 *
 * 三个"判题器自己接线"的零件，候选人改不了：
 *   1) service 的耗时/成败由 spec 给定，并把每次调用的实参记进 log.calls；
 *   2) onSuccess/onError/onFinally 由 wire() 覆盖，只负责往 log.events 里追加；
 *   3) 可见性由 applyHidden() 改 document.visibilityState 并派发冒泡的 visibilitychange。
 * 所以本题判的是"该不该调用、什么时候再调用"，不是"文案写得像不像 ahooks"。
 */
type Log = { calls: string[]; events: string[] };
type Step = { delay: number; fail?: boolean };

let log: Log = { calls: [], events: [] };

function makeService(steps: Step[]) {
  return (...args: unknown[]) => {
    const key = args.join(',');
    log.calls.push(key);
    const n = log.calls.length;
    const spec = steps[Math.min(n - 1, steps.length - 1)];
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        if (spec.fail) reject(new Error('svc-' + key));
        else resolve('#' + n + ':' + key);
      }, spec.delay);
    });
  };
}

function applyHidden(v: boolean) {
  Object.defineProperty(document, 'visibilityState', {
    configurable: true,
    get: () => (v ? 'hidden' : 'visible'),
  });
  document.dispatchEvent(new Event('visibilitychange', { bubbles: true }));
}

function wire(options: Record<string, unknown>) {
  return {
    ...options,
    onSuccess: (data: unknown) => {
      log.events.push('success:' + String(data));
    },
    onError: (e: unknown) => {
      log.events.push('error:' + String((e as Error).message));
    },
    onFinally: (params: unknown[], data: unknown, e: unknown) => {
      const key = (params ?? []).join(',');
      log.events.push(e === undefined ? 'finally:ok:' + String(data) : 'finally:err:svc-' + key);
    },
  };
}

function Probe({ service, options, argsets }: { service: any; options: any; argsets: any[][] }) {
  const res = usePollingRequest<any, any[]>(service, options);
  return (
    <div>
      <span data-testid="loading">{res.loading ? '1' : '0'}</span>
      <span data-testid="data">{res.data === undefined ? '-' : String(res.data)}</span>
      <span data-testid="error">{res.error === undefined ? '-' : String((res.error as Error).message)}</span>
      <span data-testid="calls">{log.calls.join('|') || '-'}</span>
      <span data-testid="events">{log.events.join('|') || '-'}</span>
      {argsets.map((args: unknown[], i: number) => (
        <span key={i}>
          <button data-testid={'run-' + i} onClick={() => res.run(...args)} />
          <button
            data-testid={'async-' + i}
            onClick={() => {
              Promise.resolve(res.runAsync(...args)).then(
                (v: unknown) => log.events.push('resolved:' + String(v)),
                (e: unknown) => log.events.push('reject:' + (e as Error).name),
              );
            }}
          />
        </span>
      ))}
      <button data-testid="cancel" onClick={() => res.cancel()} />
    </div>
  );
}

const tick = async (ms: number) => {
  await act(async () => {
    await vi.advanceTimersByTimeAsync(ms);
  });
};

const obs = () => ({
  // loading/data/error 走 DOM：它们只有在 React 真的重渲染后才会变，这正是要判的东西。
  // calls/events 走判题器自己的数组：它们是"外部记账"，不该依赖候选人有没有触发渲染。
  loading: screen.getByTestId('loading').textContent,
  data: screen.getByTestId('data').textContent,
  error: screen.getByTestId('error').textContent,
  calls: log.calls.join('|') || '-',
  events: log.events.join('|') || '-',
});

describe('usePollingRequest：竞态裁决与轮询续期', () => {
  beforeEach(() => {
    vi.useFakeTimers();
    log = { calls: [], events: [] };
    applyHidden(false);
  });

  afterEach(() => {
    vi.useRealTimers();
  });

  it("竞态：后发先至时，先发的那条既不写 data 也不报告任何东西", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 900}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 0})} argsets={[["slow"], ["fast"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(100);  // t=100
    await tick(0);
    // t=100
    expect(obs()).toEqual({"loading": "1", "data": "-", "error": "-", "calls": "slow", "events": "-"});
    fireEvent.click(screen.getByTestId("run-1"));
    await tick(100);  // t=200
    await tick(0);
    // t=200
    expect(obs()).toEqual({"loading": "0", "data": "#2:fast", "error": "-", "calls": "slow|fast", "events": "success:#2:fast|finally:ok:#2:fast"});
    await tick(750);  // t=950
    await tick(0);
    // t=950
    expect(obs()).toEqual({"loading": "0", "data": "#2:fast", "error": "-", "calls": "slow|fast", "events": "success:#2:fast|finally:ok:#2:fast"});
  });

  it("竞态：被覆盖的 runAsync 以 CancelledError reject，而不是静默成功", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 900}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 0})} argsets={[["slow"], ["fast"]]} />);
    fireEvent.click(screen.getByTestId("async-0"));
    await tick(100);  // t=100
    fireEvent.click(screen.getByTestId("async-1"));
    await tick(100);  // t=200
    await tick(0);
    // t=200
    expect(obs()).toEqual({"loading": "0", "data": "#2:fast", "error": "-", "calls": "slow|fast", "events": "success:#2:fast|finally:ok:#2:fast|resolved:#2:fast"});
    await tick(750);  // t=950
    await tick(0);
    // t=950
    expect(obs()).toEqual({"loading": "0", "data": "#2:fast", "error": "-", "calls": "slow|fast", "events": "success:#2:fast|finally:ok:#2:fast|resolved:#2:fast|reject:CancelledError"});
  });

  it("竞态反向：先发的那条自身失败，也只能以 CancelledError reject（业务错误被吞）", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 400, "fail": true}, {"delay": 150}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 0})} argsets={[["boom"], ["ok"]]} />);
    fireEvent.click(screen.getByTestId("async-0"));
    await tick(100);  // t=100
    fireEvent.click(screen.getByTestId("async-1"));
    await tick(150);  // t=250
    await tick(0);
    // t=250
    expect(obs()).toEqual({"loading": "0", "data": "#2:ok", "error": "-", "calls": "boom|ok", "events": "success:#2:ok|finally:ok:#2:ok|resolved:#2:ok"});
    await tick(200);  // t=450
    await tick(0);
    // t=450
    expect(obs()).toEqual({"loading": "0", "data": "#2:ok", "error": "-", "calls": "boom|ok", "events": "success:#2:ok|finally:ok:#2:ok|resolved:#2:ok|reject:CancelledError"});
  });

  it("cancel 只让结果不可见：不中止 promise、不清 data、loading 立刻归位", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 500}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 0})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("async-0"));
    await tick(100);  // t=100
    await tick(0);
    // t=100
    expect(obs()).toEqual({"loading": "1", "data": "-", "error": "-", "calls": "p", "events": "-"});
    fireEvent.click(screen.getByTestId('cancel'));
    await tick(100);  // t=200
    await tick(0);
    // t=200
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "-", "calls": "p", "events": "-"});
    await tick(400);  // t=600
    await tick(0);
    // t=600
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "-", "calls": "p", "events": "reject:CancelledError"});
  });

  it("轮询：下一次在\"上一次完成 + interval\"才发，不是从发起时刻起算", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(100);  // t=100
    await tick(0);
    // t=100
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await tick(900);  // t=1000
    await tick(0);
    // t=1000
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await tick(100);  // t=1100
    await tick(0);
    // t=1100
    expect(obs()).toEqual({"loading": "1", "data": "#1:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p"});
    await tick(100);  // t=1200
    await tick(0);
    // t=1200
    expect(obs()).toEqual({"loading": "0", "data": "#2:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p|success:#2:p|finally:ok:#2:p"});
  });

  it("轮询：请求比 interval 还慢时自动串行化，不会叠加并发", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 1500}, {"delay": 1500}, {"delay": 1500}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(1000);  // t=1000
    await tick(0);
    // t=1000
    expect(obs()).toEqual({"loading": "1", "data": "-", "error": "-", "calls": "p", "events": "-"});
    await tick(500);  // t=1500
    await tick(0);
    // t=1500
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await tick(500);  // t=2000
    await tick(0);
    // t=2000
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await tick(500);  // t=2500
    await tick(0);
    // t=2500
    expect(obs()).toEqual({"loading": "1", "data": "#1:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p"});
  });

  it("pollingErrorRetryCount:2 ⇒ 容忍 2 次，第 3 次连续失败才停（判据是 <=）", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000, "pollingErrorRetryCount": 2})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(3400);  // t=3400
    await tick(0);
    // t=3400
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "svc-p", "calls": "p|p|p", "events": "error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p"});
    await tick(4600);  // t=8000
    await tick(0);
    // t=8000
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "svc-p", "calls": "p|p|p", "events": "error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p"});
  });

  it("失败计数是\"连续\"：中途成功一次就归零，总失败 3 次也只按 1 次算", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100, "fail": true}, {"delay": 100}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000, "pollingErrorRetryCount": 1})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(6000);  // t=6000
    await tick(0);
    // t=6000
    expect(obs()).toEqual({"loading": "0", "data": "#2:p", "error": "svc-p", "calls": "p|p|p|p", "events": "error:svc-p|finally:err:svc-p|success:#2:p|finally:ok:#2:p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p"});
  });

  it("pollingErrorRetryCount 默认 -1 ⇒ 无限次：连错 5 次也还在轮询", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}, {"delay": 100, "fail": true}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(4600);  // t=4600
    await tick(0);
    // t=4600
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "svc-p", "calls": "p|p|p|p|p", "events": "error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p|error:svc-p|finally:err:svc-p"});
  });

  it("pollingWhenHidden:false ⇒ 隐藏时不排下一次，重新可见补发一次 refresh", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000, "pollingWhenHidden": false})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(100);  // t=100
    await tick(0);
    // t=100
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await act(async () => { applyHidden(true); });
    await tick(2900);  // t=3000
    await tick(0);
    // t=3000
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    await act(async () => { applyHidden(false); });
    await tick(200);  // t=3200
    await tick(0);
    // t=3200
    expect(obs()).toEqual({"loading": "0", "data": "#2:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p|success:#2:p|finally:ok:#2:p"});
  });

  it("pollingWhenHidden 默认 true ⇒ 页面隐藏也照打服务端（SRE 投诉的那条）", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await act(async () => { applyHidden(true); });
    await tick(1300);  // t=1300
    await tick(0);
    // t=1300
    expect(obs()).toEqual({"loading": "0", "data": "#2:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p|success:#2:p|finally:ok:#2:p"});
  });

  it("pollingInterval 默认 0 ⇒ 压根不进入轮询模式", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(5000);  // t=5000
    await tick(0);
    // t=5000
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
  });

  it("pollingInterval 由 0 改成 1000 不会自动启动，必须再 run 一次", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 0})} argsets={[["p"]]} />);
    fireEvent.click(screen.getByTestId("run-0"));
    await tick(100);  // t=100
    await tick(0);
    // t=100
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
    view.rerender(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    await tick(4900);  // t=5000
    await tick(0);
    // t=5000
    expect(obs()).toEqual({"loading": "0", "data": "#1:p", "error": "-", "calls": "p", "events": "success:#1:p|finally:ok:#1:p"});
  });

  it("manual:true 时初始化不启动轮询（哪怕 interval 已经为正）", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"manual": true, "pollingInterval": 1000})} argsets={[["p"]]} />);
    await tick(3000);  // t=3000
    await tick(0);
    // t=3000
    expect(obs()).toEqual({"loading": "0", "data": "-", "error": "-", "calls": "-", "events": "-"});
  });

  it("manual 默认 false ⇒ 挂载即跑 defaultParams 并开始轮询，后续复用同一批实参", async () => {
    let view: ReturnType<typeof render>;
    const service = makeService([{"delay": 100}, {"delay": 100}, {"delay": 100}, {"delay": 100}]);
    view = render(<Probe service={service} options={wire({"pollingInterval": 1000, "defaultParams": ["p"]})} argsets={[["p"]]} />);
    await tick(1300);  // t=1300
    await tick(0);
    // t=1300
    expect(obs()).toEqual({"loading": "0", "data": "#2:p", "error": "-", "calls": "p|p", "events": "success:#1:p|finally:ok:#1:p|success:#2:p|finally:ok:#2:p"});
  });

});

